typedef float rational_t;

extern "C" float sqrtf(float);
#define __fsqrt sqrtf
#define assert(e) ((void)0)

template <class T>
inline const T& max(const T& a, const T& b)
{
  return a < b ? b : a;
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(T _x, T _y, T _z) : x(_x), y(_y), z(_z) {}
  inline vector3d(const vector3d& v) : x(v.x), y(v.y), z(v.z) {}
  inline vector3d operator-(const vector3d& v) const { return vector3d(x-v.x,y-v.y,z-v.z); }
  inline vector3d operator+(const vector3d& v) const { return vector3d(x+v.x,y+v.y,z+v.z); }
  inline vector3d operator*(T s) const { return vector3d(x*s,y*s,z*s); }
  inline T length2() const { return x*x + y*y + z*z; }
  inline bool is_valid() const { return true; }
};

class bounding_box
{
public:
  vector3d vmin;
  vector3d vmax;

  bounding_box()
    : vmin(3.402823466e+38F,3.402823466e+38F,3.402823466e+38F),
      vmax(-3.402823466e+38F,-3.402823466e+38F,-3.402823466e+38F)
  {}

  vector3d center() const { return (vmax+vmin)*0.5F; }

  void accumulate(const vector3d& p)
  {
    if (vmin.x>p.x) vmin.x=p.x;
    if (vmin.y>p.y) vmin.y=p.y;
    if (vmin.z>p.z) vmin.z=p.z;
    if (vmax.x<p.x) vmax.x=p.x;
    if (vmax.y<p.y) vmax.y=p.y;
    if (vmax.z<p.z) vmax.z=p.z;
  }
};

class hw_rasta_vert
{
public:
  vector3d xyz;
  char released_layout[48];
};

class vr_pmesh
{
  char released_layout0[24];
protected:
  hw_rasta_vert *xverts;
  char released_layout1[12];
  int num_wedges;
  char released_layout2[76];
  vector3d center;
  rational_t radius;
public:
  inline int get_num_wedges() const { return num_wedges; }
  virtual void compute_info();
};

void vr_pmesh::compute_info()
{
  int i;
  bounding_box box;

  //float radius2 = 0.0f;
  for(i = get_num_wedges(); --i>=0; )
  {
    const vector3d& p = xverts[i].xyz;
    assert(p.is_valid());
    box.accumulate(p);
    //radius2 = max(p.length2(), radius2);
  }
  //radius = __fsqrt(radius2);
  center = box.center();
  assert(center.is_valid());
  float radius_rel_center2 = 0.0f;
  for(i = get_num_wedges(); --i>=0; )
  {
    vector3d delta = xverts[i].xyz - center;
    radius_rel_center2 = max( delta.length2(), radius_rel_center2 );
  }
  radius = __fsqrt(radius_rel_center2);
}
